style.css:
@-moz-document url-prefix("https://yue3ds.uuscrm.vip/") {
/* Background utama */
  html, body {
    background: url("https://i.ibb.co/RG3WxDzn/pink.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Hapus background putih di semua container */
  div, section, main, aside, header, footer,
  .el-container, .el-main, .el-aside, .el-header, .el-footer,
  .chat-container, .chat-box, .chat-content, .friend-list, .group-list,
  .el-card, .content {
    background: transparent !important;
    box-shadow: none !important;
  }

  /* Chat bubbles tetap ada transparansi biar teks terbaca */
  .message-item .text,
  .message-item .content,
  .chat-message {
    background: rgba(0,0,0,0.4) !important;
    color: #fff !important;
    border-radius: 8px !important;
    padding: 6px 10px !important;
  }

  /* Input area */
  input, textarea {
    background: rgba(0,0,0,0.5) !important;
    color: #fff !important;
    border: 1px solid rgba(255,255,255,0.2) !important;
  }

  /* Tombol */
  .el-button, .send {
    background: rgba(255, 87, 34, 0.9) !important;
    color: #fff !important;
    border: none !important;
  }

  /* Scroll bar dark */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,0.3);
    border-radius: 4px;
  }
}
